.vcontainer {
        margin: 0 auto 0;
        position: relative;
        box-shadow: 0 10px 20px -5px #000;
        width: 100%;
        background-color: #000000;
}
#streaming {
        width: 100%;
        max-height: 580px;
        z-index: 800;
        cursor: pointer;
        position: relative;
}
.marquee {
        color: #70E847;
        padding: 5px 0;
        margin: 0 auto;
        white-space: nowrap;
        overflow: hidden;
        box-sizing: border-box;
        border-top: 1px rgb(84, 86, 84) solid;
        border-bottom: 1px rgb(84, 86, 84) solid;
}
.marquee span {
        display: inline-block;
        padding-left: 100%;
        text-indent: 0;
        animation: marquee 15s linear infinite;
}
.marquee span:hover {
        animation-play-state: paused
}
.img-backdrop {
        width: 100%;
        height: auto;
        max-height: 580px;
}
/* Make it move */
@keyframes marquee {
    0%   { transform: translate(0, 0); }
    100% { transform: translate(-100%, 0); }
}

